function decodeHex(hex: string): Uint8Array<ArrayBuffer> {
	const bytes = new Uint8Array(hex.length / 2);
	for (let index = 0; index < bytes.length; index += 1) {
		bytes[index] = Number.parseInt(hex.slice(index * 2, index * 2 + 2), 16);
	}
	return bytes;
}

// Mirrors the protoc-generated .bin files so tests do not depend on filesystem
// access (the test environment replaces node:fs with an in-memory filesystem).
export const wireFixtures = {
	logsRequest: decodeHex(
		"",
	),
	metricsRequest: decodeHex(
		"",
	),
	logsResponseLarge: decodeHex("0a1708ffffffffffffffff7f120b6c6172676520636f756e74"),
	logsResponseNegative: decodeHex(
		"0a2308ffffffffffffffffff011216696e76616c6964206e6567617469766520636f756e74",
	),
	logsResponseLargeUnknown: decodeHex("0a1708ffffffffffffffff7f120b6c6172676520636f756e747807"),
	metricsResponseLarge: decodeHex("0a1208818080808080801012077061727469616c"),
} as const;
